import{_ as t,C as r,o as n,c as s,ag as o,E as i}from"./chunks/framework.CtWPcAmt.js";const m=JSON.parse('{"title":"Booking Management","description":"","frontmatter":{},"headers":[],"relativePath":"orders/booking-management.md","filePath":"orders/booking-management.md","lastUpdated":1786088921000}'),l={name:"orders/booking-management.md"};function c(d,e,g,h,p,u){const a=r("ImagePopup");return n(),s("div",null,[e[0]||(e[0]=o('<h1 id="booking-management" tabindex="-1">Booking Management <a class="header-anchor" href="#booking-management" aria-label="Permalink to &quot;Booking Management&quot;">​</a></h1><p>Sellers can list <strong>bookable</strong> products — items or services a customer reserves for a date or time, such as an appointment, rental, event ticket, or table. When a customer books one, the reservation appears in the seller&#39;s <strong>Sales → Bookings</strong>.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>What a bookable product is</li><li>Where a seller sees their bookings</li><li>How bookings relate to orders</li></ul></div><h2 id="bookable-products" tabindex="-1">Bookable products <a class="header-anchor" href="#bookable-products" aria-label="Permalink to &quot;Bookable products&quot;">​</a></h2><p>A booking product is created like any other listing — choose <strong>Bookable</strong> as the product kind in the <a href="/catalog/product-management#the-what-kind-of-product-funnel">create flow</a>. Bookable products carry availability (dates, time slots, or quantities) that customers pick from when they reserve, and support several booking types (appointment, table, event, rental, and default).</p><h2 id="the-bookings-screen" tabindex="-1">The bookings screen <a class="header-anchor" href="#the-bookings-screen" aria-label="Permalink to &quot;The bookings screen&quot;">​</a></h2><p>Open <strong>Sales → Bookings</strong> in the Seller Panel. It offers two views you can switch between:</p>',7)),i(a,{src:"/images/booking-management/bookings-list.png",alt:"Seller bookings"}),e[1]||(e[1]=o('<ul><li><strong>List</strong> — a table of reservations showing the <strong>ID</strong>, <strong>Order ID</strong>, <strong>quantity</strong>, and the reserved <strong>From / To</strong> window; searchable and filterable by date range, and exportable.</li><li><strong>Calendar</strong> — the same reservations laid out by date, so you can see how a day or week is filling up, with each entry&#39;s details, order, price, and status.</li></ul><h2 id="bookings-and-orders" tabindex="-1">Bookings and orders <a class="header-anchor" href="#bookings-and-orders" aria-label="Permalink to &quot;Bookings and orders&quot;">​</a></h2><p>A booking is placed through the normal checkout, so each reservation is anchored to a seller order — the <strong>View</strong> action opens the <a href="/orders/order-management">order</a> it belongs to. You invoice, fulfil, and get paid for a booking the same way as any other order.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Keep your bookable product&#39;s availability accurate so customers can only reserve slots you can actually honour — an over-booked slot means a cancellation, which hurts your <a href="/sellers/seller-account-health">account health</a>.</p></div>',4))])}const k=t(l,[["render",c]]);export{m as __pageData,k as default};
